package io.knowledgebrain.learning;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class CourseProgressShareApiTest {
 CourseProgressApiTest f;CourseProgressShareStore store;CourseProgressShareController api;CourseContextClient.Sharing a;
 @BeforeEach void setup(){f=new CourseProgressApiTest();f.setup();store=mock(CourseProgressShareStore.class);a=new CourseContextClient.Sharing(f.ref,3,true,"OWNER",2,List.of());when(f.client.sharing(eq(f.group),eq(f.course),eq(f.token),anyString(),eq(List.of()))).thenReturn(a);api=new CourseProgressShareController(store,f.client,new RoadmapController(mock(RoadmapStore.class),mock(SpaceAuthorizationClient.class),new SimpleMeterRegistry(),"https://localhost:8443"),new SimpleMeterRegistry(),"https://localhost:8443");}
 MockHttpServletRequest req(String input){var r=f.req("PUT",input);r.removeHeader("If-Match");r.addHeader("If-Match","\"cs0\"");return r;}
 String input(){return "{\"state\":\"SHARED\",\"progressVersion\":1,\"policyVersion\":3,\"courseVersion\":3,\"enrollmentVersion\":1,\"membershipVersion\":2}";}
 void status(int code,org.junit.jupiter.api.function.Executable op){assertEquals(code,assertThrows(ResponseStatusException.class,op).getStatusCode().value());}
 @Test void exactObservedVersionsAndActorComeFromAuthority()throws Exception{var response=api.change(f.group.toString(),f.course.toString(),req(input()));assertEquals("\"cs0\"",response.getHeaders().getETag());verify(store).change(eq(a),eq(0L),eq("SHARED"),eq(1L),anyString());}
 @Test void changedPreviewContextDoesNotReachStore(){status(409,()->api.change(f.group.toString(),f.course.toString(),req(input().replace("membershipVersion\":2","membershipVersion\":1"))));verifyNoInteractions(store);}
 @Test void rejectsForgedActorUnknownFieldsDuplicateAndNonIntegralVersions(){for(var v:List.of(input().replace("}",",\"participantId\":\"forged\"}"),input().replace("progressVersion\":1","progressVersion\":1.0"),input().replace("}",",\"state\":\"SHARED\"}"),"{\"state\":\"WITHDRAWN\",\"progressVersion\":1}")){status(400,()->api.change(f.group.toString(),f.course.toString(),req(v)));}verifyNoInteractions(store);}
 @Test void strongShareVersionAndSameOriginSessionAreRequired(){var missing=req(input());missing.removeHeader("If-Match");status(428,()->api.change(f.group.toString(),f.course.toString(),missing));for(var tag:List.of("*","W/\"cs0\"","\"cs01\"","\"cp0\"")){var r=req(input());r.removeHeader("If-Match");r.addHeader("If-Match",tag);status(400,()->api.change(f.group.toString(),f.course.toString(),r));}var cross=req(input());cross.removeHeader("Origin");cross.addHeader("Origin","https://other.invalid");status(403,()->api.change(f.group.toString(),f.course.toString(),cross));var duplicate=req(input());duplicate.addHeader("Cookie","__Host-brain_guest="+f.token);status(401,()->api.change(f.group.toString(),f.course.toString(),duplicate));verifyNoInteractions(store);}
 @Test void memberCannotReadOwnerRoster(){status(403,()->api.list(f.group.toString(),f.course.toString(),f.req("GET",null)));verifyNoInteractions(store);}
 @Test void withdrawalDoesNotRequirePublishContextFields()throws Exception{api.change(f.group.toString(),f.course.toString(),req("{\"state\":\"WITHDRAWN\"}"));verify(store).change(eq(a),eq(0L),eq("WITHDRAWN"),eq(0L),anyString());}
}
